html, body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #1b2220; background: #fff; }
#planning { padding: 8px 12px 10px; display: flex; flex-direction: column; gap: 6px; }
#entete, .ligne { display: grid; grid-template-columns: 190px 1fr; align-items: center; }
#entete .axe { position: relative; height: 18px; }
#entete .heure { position: absolute; transform: translateX(-50%); font-size: 11px; color: #4d5955; font-variant-numeric: tabular-nums; }
.ligne { min-height: 34px; border-top: 1px solid #e3e7e4; }
.nom { font-size: 12px; line-height: 1.3; padding-right: 8px; }
.nom b { display: block; font-size: 12.5px; }
.nom span { color: #4d5955; font-variant-numeric: tabular-nums; }
.piste { position: relative; height: 28px; }
.grille { position: absolute; top: 0; bottom: 0; width: 1px; background: #eef1ef; }
.trajet { position: absolute; top: 12px; height: 4px; border-radius: 2px; opacity: 0.45; }
.bloc {
  position: absolute; top: 4px; height: 20px; border-radius: 3px; color: #fff; font-size: 10.5px; font-weight: 700;
  display: flex; align-items: center; justify-content: center; overflow: hidden; min-width: 14px;
  box-shadow: 0 0 0 1px #fff;
}
.bloc.livraison { background: #0e5c58; }
.bloc.ramassage { background: #b07800; }
#vide { display: none; padding: 20px; text-align: center; color: #4d5955; font-size: 13px; }
#cle { display: flex; flex-wrap: wrap; gap: 14px; font-size: 11.5px; color: #4d5955; padding-top: 4px; }
#cle span { display: inline-flex; align-items: center; gap: 5px; }
#cle i.bloc { position: static; width: 14px; height: 10px; display: inline-block; box-shadow: none; }
#cle i.trajet { position: static; width: 22px; height: 4px; display: inline-block; background: #7a8581; }

