// Planning des tournées : une ligne par camion, les arrêts sur l'axe des heures.
// Modèle : même format que la carte ({ tournees: [{ camion, couleur, heure_depart,
//          heure_retour, km, etapes: [{ rang, heure, duree_min, action, chantier }] }] }).

function minutes(heure) {
  if (!heure) return null;
  const [h, m] = String(heure).split(":").map(Number);
  return h * 60 + (m || 0);
}

function echapper(t) {
  return String(t ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}

function afficher(modele) {
  const tournees = (modele && modele.tournees) || [];
  const entete = document.getElementById("entete");
  const lignes = document.getElementById("lignes");
  document.getElementById("vide").style.display = tournees.length ? "none" : "block";
  document.getElementById("cle").style.display = tournees.length ? "flex" : "none";
  entete.innerHTML = "";
  lignes.innerHTML = "";
  if (!tournees.length) return;

  // Fenêtre affichée : de l'heure pleine avant le premier départ à celle après le dernier retour.
  const bornes = tournees.flatMap(t => [minutes(t.heure_depart), minutes(t.heure_retour)]).filter(v => v != null);
  const debut = Math.min(6 * 60, Math.floor(Math.min(...bornes) / 60) * 60);
  const fin = Math.max(17 * 60, Math.ceil(Math.max(...bornes) / 60) * 60);
  const pct = m => ((m - debut) / (fin - debut)) * 100;

  const heures = [];
  for (let h = debut; h <= fin; h += 60) heures.push(h);
  entete.innerHTML = '<div></div><div class="axe">' +
    heures.map(h => `<span class="heure" style="left:${pct(h)}%">${String(h / 60).padStart(2, "0")}h</span>`).join("") +
    "</div>";

  lignes.innerHTML = tournees.map(t => {
    const depart = minutes(t.heure_depart);
    const retour = minutes(t.heure_retour);
    const grille = heures.map(h => `<div class="grille" style="left:${pct(h)}%"></div>`).join("");
    const trajet = depart != null && retour != null
      ? `<div class="trajet" style="left:${pct(depart)}%;width:${pct(retour) - pct(depart)}%;background:${t.couleur}"></div>`
      : "";
    const blocs = t.etapes.map(e => {
      const arrivee = minutes(e.heure);
      if (arrivee == null) return "";
      const duree = Math.max(Number(e.duree_min) || 15, 5);
      const titre = `${e.heure} · ${e.action} · ${e.chantier} (${duree} min)`;
      return `<div class="bloc ${e.action === "ramassage" ? "ramassage" : "livraison"}" ` +
        `style="left:${pct(arrivee)}%;width:${pct(arrivee + duree) - pct(arrivee)}%" title="${echapper(titre)}">${e.rang}</div>`;
    }).join("");
    const infos = `${echapper(t.heure_depart)} → ${echapper(t.heure_retour)}${t.km != null ? " · " + t.km + " km" : ""}`;
    return `<div class="ligne"><div class="nom"><b style="color:${t.couleur}">${echapper(t.camion)}</b>` +
      `<span>${infos}</span></div><div class="piste">${grille}${trajet}${blocs}</div></div>`;
  }).join("");
}

appsmith.onReady(() => {
  afficher(appsmith.model);
  appsmith.onModelChange(modele => afficher(modele));
});

